'use strict';
const PALETTE_STYLE = getComputedStyle(document.documentElement);
const paletteColor = name => PALETTE_STYLE.getPropertyValue(`--${name}`).trim();
const COLORS = Object.fromEntries(['called','reached','completed','unreached'].map(name=>[name,paletteColor(name)]));
Object.assign(COLORS,{grey:paletteColor('graph-gray'),noData:paletteColor('graph-no-data'),text:paletteColor('text-secondary'),grid:paletteColor('border'),male:paletteColor('male'),female:paletteColor('female')});
const CATEGORICAL = Array.from({length:10},(_,index)=>paletteColor(`categorical-${index+1}`));
const POSITIVE_SCALE = Array.from({length:5},(_,index)=>paletteColor(`positive-${index+1}`));
const LABELS = {State:'State',Gender:'Gender',Locality:'Locality',Community:'Community','Type of Support':'Support type',SupportProject:'Project','Age group':'Age group'};
const PHONE_MAP = new Map(DATA.people.map(person => [person.person_id,person]));
const ANSWER_MAP = new Map();
for (const row of DATA.answers) { if (!ANSWER_MAP.has(row.person_id)) ANSWER_MAP.set(row.person_id,{}); ANSWER_MAP.get(row.person_id)[row.question]=row.answer; }
const QUESTION_PRESENCE = new Set((DATA.question_presence||[]).map(row=>`${row.person_id}|${row.question}`));
let currentPage='overview', charts=[], exportRows=[], scope=null;
const local = {comparison:'Gender',question:'R1Q06',surveyGroup:'State',mapMetric:'contact',callDimension:'date'};
const number = value => Number(value || 0).toLocaleString('en-GB');
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const categoryLabel = (value,attribute) => attribute==='Gender'&&['Male','Female'].includes(value)?`<span class="category-label"><b style="background:${value==='Male'?COLORS.male:COLORS.female}"></b>${escapeHTML(value)}</span>`:escapeHTML(value);
const rate = (numerator,denominator,suppress=false) => denominator ? (suppress && denominator<10 ? 'Withheld' : `${(100*numerator/denominator).toFixed(1)}%`) : '—';
const sum = (items,property) => items.reduce((total,item)=>total+Number(item[property]||0),0);
const count = (items,predicate) => items.filter(predicate).length;
const groupBy = (items,property) => {const map=new Map();for(const item of items){const key=typeof property==='function'?property(item):item[property];if(!map.has(key))map.set(key,[]);map.get(key).push(item);}return map;};
const el = id => document.getElementById(id);

function getScope(){
  const values=Object.fromEntries(['state','gender','from','to','outcome','attempts','completion','support'].map(id=>[id,el(id).value]));
  const exposed=Boolean(values.from||values.to||values.outcome);
  let people=DATA.people.filter(person=>(!values.state||person.State===values.state)&&(!values.gender||person.Gender===values.gender)&&(!values.support||person['Type of Support']===values.support));
  const selectedCalls=DATA.calls.filter(call=>(!values.from||call.date>=values.from)&&(!values.to||call.date<=values.to)&&(!values.outcome||call.status===values.outcome));
  const exposureIDs=new Set(selectedCalls.map(call=>call.person_id));
  if(exposed)people=people.filter(person=>exposureIDs.has(person.person_id));
  if(values.attempts)people=people.filter(person=>values.attempts==='4'?person.attempts>=4:person.attempts===Number(values.attempts));
  if(values.completion)people=people.filter(person=>values.completion==='completed'?person.response_complete:values.completion==='answered'?person.reached&&!person.response_complete:values.completion==='unreached'?person.attempts>0&&!person.reached:person.attempts===0);
  const ids=new Set(people.map(person=>person.person_id));
  const calls=selectedCalls.filter(call=>ids.has(call.person_id));
  return {people,calls,master:people.filter(person=>person.in_master),called:people.filter(person=>person.attempts>0),reached:people.filter(person=>person.reached),completed:people.filter(person=>person.response_complete),exposed,values,ids};
}

