function simpleText(value){let text=String(value??'');for(const [pattern,replacement] of SIMPLE_PHRASES)text=text.replace(pattern,replacement);return text;}
function simplifyRenderedText(root){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  while(walker.nextNode())walker.currentNode.nodeValue=simpleText(walker.currentNode.nodeValue);
  for(const element of root.querySelectorAll('[title],[aria-label]'))for(const attribute of ['title','aria-label'])if(element.hasAttribute(attribute))element.setAttribute(attribute,simpleText(element.getAttribute(attribute)));
}
function heading(title,description,badge='From survey files'){
  return `<div class="page-heading"><div><h2>${title}</h2><p class="subtitle">${description}</p></div><span class="badge">${badge}</span></div>`;
}
function metric(label,value,note,color=''){
  return `<div class="metric ${color}"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;
}
function section(title,note,body,extra=''){
  return `<section class="section"><div class="section-head"><div><h3>${title}</h3><p>${note}</p></div>${extra}</div>${body}</section>`;
}
function chartBox(id,size='') {return `<div class="chart ${size}"><canvas id="${id}" role="img" aria-label="${id.replaceAll('-',' ')}"></canvas></div>`;}
function table(headers,rows){
  if(!rows.length)return '<div class="empty">No records in this selection.</div>';
  return `<div class="table-wrap"><table><thead><tr>${headers.map(header=>`<th scope="col">${header}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function legend(){return `<div class="legend">${[['Called',COLORS.called],['Reached',COLORS.reached],['Completed',COLORS.completed],['Not reached',COLORS.unreached]].map(([name,color])=>`<span><b style="background:${color}"></b>${name}</span>`).join('')}</div>`;}
function drawChart(id,labels,datasets,options={}){
  if(!el(id))return;
  const {horizontal=false,percent=false,stacked=false,type='bar'}=options;
  charts.push(new Chart(el(id),{type,data:{labels:labels.map(simpleText),datasets:datasets.map(dataset=>({...dataset,label:simpleText(dataset.label||''),borderRadius:2,maxBarThickness:25,borderWidth:type==='line'?2:0,pointRadius:type==='line'?3:0}))},options:{responsive:true,maintainAspectRatio:false,indexAxis:horizontal?'y':'x',animation:false,plugins:{legend:{display:datasets.length>1,position:'bottom',labels:{usePointStyle:true,pointStyle:'rect',padding:18,font:{size:12}}},tooltip:{backgroundColor:paletteColor('text-primary'),titleColor:paletteColor('surface'),bodyColor:paletteColor('surface'),callbacks:{label:context=>`${simpleText(context.dataset.label)}: ${context.formattedValue}${percent?'%':''}`}}},scales:{x:{stacked,beginAtZero:true,grid:{display:horizontal,color:COLORS.grid},ticks:{color:COLORS.text,font:{size:12},maxRotation:45,...(!horizontal&&percent?{callback:value=>value+'%'}:{})},...(horizontal&&percent?{max:100,ticks:{callback:value=>value+'%',color:COLORS.text}}:{})},y:{stacked,beginAtZero:true,grid:{display:!horizontal,color:COLORS.grid},ticks:{color:COLORS.text,font:{size:12}},...(!horizontal&&percent?{max:100,ticks:{callback:value=>value+'%',color:COLORS.text}}:{})}}}}));
}

function masterComparisons(attribute){
  const completedTotal=count(scope.master,person=>person.response_complete);
  return [...groupBy(scope.master,attribute)].map(([category,people])=>{
    const called=count(people,person=>person.attempts>0),reached=count(people,person=>person.reached),completed=count(people,person=>person.response_complete);
    return {category,master:people.length,master_records:sum(people,'master_records'),called,reached,completed,nonresponse:people.length-completed,attempts:scope.calls.filter(call=>people.some(person=>person.person_id===call.person_id)).length,masterShare:scope.master.length?100*people.length/scope.master.length:0,responseShare:completedTotal?100*completed/completedTotal:0,difference:completedTotal&&scope.master.length?100*completed/completedTotal-100*people.length/scope.master.length:null};
  }).sort((first,second)=>second.master-first.master);
}

function renderOverview(){
  const s=scope,answered=count(s.calls,call=>call.answered),started=count(s.called,person=>person.started_proxy),intro=count(s.called,person=>person.intro_snapshot),repeat=count(s.called,person=>person.attempts>1);
  const states=masterComparisons('State'),linkedCompleted=count(s.master,person=>person.response_complete);
  const over=[...states].filter(row=>row.difference!==null).sort((a,b)=>b.difference-a.difference)[0];
  const under=[...states].filter(row=>row.difference!==null).sort((a,b)=>a.difference-b.difference)[0];
  const funnel=[['Observed targeted',s.called.length,COLORS.called],['Ever reached',s.reached.length,COLORS.reached],['Intro flag · snapshot',intro,paletteColor('azure')],['Started · Q01 proxy',started,POSITIVE_SCALE[2]],['Completed response',s.completed.length,COLORS.completed]];
  const abandoned=count(s.called,person=>person.started_proxy&&!person.response_complete);
  const flagged=count(s.people,person=>person.log_complete),unmatched=count(s.called,person=>!person.in_master);
  el('content').innerHTML=heading('Coverage is broad. Completed responses are selective.','Keep phone contacts, call-log rows and verified response records separate. Counts below reflect the current contact cohort.')+
    `<div class="metrics">${metric('Master beneficiary records',number(sum(s.master,'master_records')),`${number(s.master.length)} distinct master phone keys`)}${metric('Unique contacts called',number(s.called.length),'Observed targeting proxy; no allocation list','called')}${metric('Observed call attempts',number(s.calls.length),'Unique Delivery ID log rows; carrier retries unknown','called')}${metric('Ever reached contacts',number(s.reached.length),`${rate(s.reached.length,s.called.length)} of called contacts · all-export reach`,'reached')}${metric('Completed response records',number(s.completed.length),`${rate(s.completed.length,s.called.length)} of called contacts`,'completed')}${metric('Completion among reached',rate(s.completed.length,s.reached.length),`${number(s.completed.length)} / ${number(s.reached.length)} ever-reached contacts`,'completed')}${metric('Attempt answer rate',rate(answered,s.calls.length),`${number(answered)} answered / ${number(s.calls.length)} selected log rows`,'reached')}${metric('Called, never answered',number(s.called.length-s.reached.length),`${rate(s.called.length-s.reached.length,s.called.length)} of called contacts`,'unreached')}</div>`+
    `<div class="split">${section('The contact-to-response funnel','Counts are unique phone keys, not individual people. Percentages use called contacts.',funnel.map(([label,value,color])=>`<div class="funnel-row"><span>${label}</span><div class="funnel-track"><div class="funnel-fill" style="width:${s.called.length?100*value/s.called.length:0}%;background:${color}"></div></div><span class="count">${number(value)}</span><span class="rate">${rate(value,s.called.length)}</span></div>`).join('')+`<p class="funnel-detail">Master roster is not a nested stage: ${number(unmatched)} called contacts are unmatched. Intro/start flags and completed answers are undated snapshots. Survey completion / started proxy: ${rate(s.completed.length,started)} (${number(s.completed.length)}/${number(started)}).</p><div class="mini-stats"><div><span>${number(abandoned)}</span><p>Started proxy, no completed record</p></div><div><span>${number(s.reached.length-s.completed.length)}</span><p>Answered, no completed record</p></div><div><span>${number(count(s.master,person=>person.attempts===0))}</span><p>Master contacts not called</p></div></div>`)}
    ${section('What stands out','Differences in these records do not explain why someone answered or finished.',`<div class="insight"><h4>${number(flagged)} call records show completion; ${number(s.completed.length)} finished surveys are in the response file</h4><p>The call-system flag and the completed-survey file do not match. The completed-survey file is used for answer results.</p></div><div class="insight"><h4>${over&&under?`${escapeHTML(over.category)} has a larger share of replies; ${escapeHTML(under.category)} has a smaller share`:'List comparison is not available'}</h4><p>${over?`${over.responseShare.toFixed(1)}% of ${number(linkedCompleted)} people who finished and match the list are from ${escapeHTML(over.category)}; ${over.masterShare.toFixed(1)}% of the beneficiary list is from this state.`:'No linked comparison is available for these filters.'}</p></div><div class="insight"><h4>${rate(repeat,s.called.length)} of phone numbers were called more than once</h4><p>${number(repeat)} of ${number(s.called.length)} numbers. Average calls per number: ${s.called.length?(s.calls.length/s.called.length).toFixed(2):'—'}.</p></div>`)}</div>`;
  exportRows=[{metric:'Master records',count:sum(s.master,'master_records')},{metric:'Master contact keys',count:s.master.length},{metric:'Called contacts',count:s.called.length},{metric:'Selected call-log rows',count:s.calls.length},{metric:'Ever reached',count:s.reached.length},{metric:'Answered log rows',count:answered},{metric:'Unanswered log rows',count:s.calls.length-answered},{metric:'Completed raw responses',count:s.completed.length},{metric:'Started proxy',count:started},{metric:'Started proxy without completed response',count:abandoned},{metric:'Called never answered',count:s.called.length-s.reached.length},{metric:'Master never reached including uncalled',count:count(s.master,person=>!person.reached)},{metric:'Repeat-contact count',count:repeat},{metric:'Contact rate percent',numerator:s.reached.length,denominator:s.called.length,value:rate(s.reached.length,s.called.length)},{metric:'Completion among reached percent',numerator:s.completed.length,denominator:s.reached.length,value:rate(s.completed.length,s.reached.length)}];
}

const geographyView={level:'Locality',search:'',gap:'all'};

function geographicGroups(level){
  const fields=level==='State'?['State']:level==='Locality'?['State','Locality']:['State','Locality','Community'];
  const attemptsByPerson=new Map();
  for(const call of scope.calls){attemptsByPerson.set(call.person_id,(attemptsByPerson.get(call.person_id)||0)+1);}
  const completedTotal=count(scope.master,person=>person.response_complete);
  return [...groupBy(scope.master,person=>JSON.stringify(fields.map(field=>person[field])))].map(([,people])=>{
    const called=count(people,person=>person.attempts>0),reached=count(people,person=>person.reached),completed=count(people,person=>person.response_complete);
    const masterShare=scope.master.length?100*people.length/scope.master.length:null;
    const responseShare=completedTotal?100*completed/completedTotal:null;
    return {level,state:people[0].State,locality:level==='State'?'':people[0].Locality,community:level==='Community'?people[0].Community:'',category:people[0][level],
      master:people.length,master_records:sum(people,'master_records'),called,reached,completed,
      attempts:people.reduce((total,person)=>total+(attemptsByPerson.get(person.person_id)||0),0),
      uncalled:people.length-called,neverAnswered:called-reached,answeredIncomplete:reached-completed,
      nonresponse:people.length-completed,invalidPhones:count(people,person=>!person.phone_valid),
      repeatContacts:count(people,person=>person.attempts>1),started:count(people,person=>person.started_proxy),
      masterShare,responseShare,difference:responseShare===null?null:responseShare-masterShare,
      representationIndex:responseShare===null||!masterShare?null:responseShare/masterShare,
      expectedAtRosterShare:completedTotal?completedTotal*people.length/scope.master.length:null};
  }).sort((first,second)=>second.master-first.master||first.state.localeCompare(second.state)||first.category.localeCompare(second.category));
}

function geographyExport(row){
  return {table:row.level,state:row.state,locality:row.locality,community:row.community,
    master_phone_keys:row.master,master_records:row.master_records,called:row.called,selected_attempts:row.attempts,
    ever_reached:row.reached,completed:row.completed,uncalled:row.uncalled,called_never_answered:row.neverAnswered,
    started_q01_proxy:row.started,started_proxy_no_completed_record:row.started-row.completed,
    answered_no_completed_record:row.answeredIncomplete,nonresponses:row.nonresponse,
    invalid_master_phone_keys:row.invalidPhones,repeat_contacts_full_export:row.repeatContacts,
    calling_coverage_rate:rate(row.called,row.master,true),contact_rate_called:rate(row.reached,row.called,true),
    completion_rate_called:rate(row.completed,row.called,true),completion_rate_reached:rate(row.completed,row.reached,true),
    completion_rate_master:rate(row.completed,row.master,true),master_share:rate(row.master,scope.master.length,true),
    completion_rate_started_proxy:rate(row.completed,row.started,true),
    completer_share:rate(row.completed,count(scope.master,person=>person.response_complete),true),
    representation_index:count(scope.master,person=>person.response_complete)>=10?row.representationIndex:'Withheld',
    share_difference_pp:count(scope.master,person=>person.response_complete)>=10?row.difference:'Withheld',
    proportional_benchmark_completed:count(scope.master,person=>person.response_complete)>=10?row.expectedAtRosterShare:'Withheld',
    small_completed_base:row.completed<10};
}

function renderGeography(){
  const rows=geographicGroups('State'),localities=geographicGroups('Locality'),communities=geographicGroups('Community');
  if(!rows.length){
    el('content').innerHTML=heading('No master-linked geography in this cohort.','Unmatched records remain in overall call and survey totals; they are not assigned to the master geographic baseline.','Excluded from roster comparison')+
      `<div class="notice info">${number(scope.people.length)} selected contact keys, ${number(scope.calls.length)} selected call rows and ${number(scope.completed.length)} completed-response records have no master-linked geography for this comparison.</div><div class="empty">No eligible master state, locality or community records.</div>`;
    exportRows=[{table:'Geographic exclusion',master_phone_keys:0,unmatched_contact_keys:scope.people.length,selected_call_rows:scope.calls.length,unmatched_completed_responses:scope.completed.length}];
    return;
  }
  const totalMaster=scope.master.length,totalCalled=sum(rows,'called'),totalReached=sum(rows,'reached'),totalCompleted=sum(rows,'completed');
  const low=rows.filter(row=>row.called>=10).sort((a,b)=>a.reached/a.called-b.reached/b.called)[0];
  const under=rows.filter(row=>row.difference!==null&&row.master>=10).sort((a,b)=>a.difference-b.difference)[0];
  const over=rows.filter(row=>row.difference!==null&&row.master>=10).sort((a,b)=>b.difference-a.difference)[0];
  const largestCommunity=[...communities].sort((a,b)=>b.completed-a.completed)[0];
  const zeroCompletionCommunities=communities.filter(row=>row.completed===0);
  const priority=[...rows].sort((a,b)=>b.neverAnswered-a.neverAnswered)[0];
  const pp=value=>value===null||totalCompleted<10?'Withheld':`${value>0?'+':''}${value.toFixed(1)} pp`;
  const stateButton=row=>`<button class="geography-state" data-geo-state="${escapeHTML(row.state)}" title="Filter all pages to ${escapeHTML(row.state)}">${escapeHTML(row.state)}<i data-lucide="chevron-right"></i></button>`;
  const metricSelect=`<div class="control"><label>Map measure<select id="map-metric"><option value="coverage">Calling coverage / master</option><option value="contact">Contact rate / called</option><option value="completion">Completion rate / called</option><option value="reachedCompletion">Completion / reached</option><option value="masterCompletion">Completion / master</option><option value="count">Completed respondents</option></select></label></div>`;
  el('content').innerHTML=heading('Where are contacts reached, and who remains missing?','State, locality and community performance against the master roster. All demographic and calling-exposure filters apply; reach and completion remain full-export contact evidence.','Master-linked geography')+
    `<div class="metrics">${metric('Master contacts called',rate(totalCalled,totalMaster,true),`${number(totalCalled)} / ${number(totalMaster)} master keys`,'called')}${metric('Ever reached / called',rate(totalReached,totalCalled,true),`${number(totalReached)} / ${number(totalCalled)} called master contacts`,'reached')}${metric('Completed / reached',rate(totalCompleted,totalReached,true),`${number(totalCompleted)} / ${number(totalReached)} reached master contacts`,'completed')}${metric('Communities without completions',number(zeroCompletionCommunities.length),`${number(zeroCompletionCommunities.length)} / ${number(communities.length)} communities · ${number(sum(zeroCompletionCommunities,'master'))} master keys`,'unreached')}</div>`+
    `<div class="split equal">${section('Coverage across programme states','White = outside this roster/cohort or rate denominator below 10.','<div id="state-map" class="map-container"></div><div class="map-key"><span>Lower</span><div class="scale"></div><span>Higher</span></div><p id="map-scale-note" class="table-note"></p><p class="map-attribution">geoBoundaries gbOpen · 2020 boundaries · CC BY 3.0 IGO. Al Jazeera uses the Gezira spelling alias. State boundaries only; no locality/community coordinates were supplied. Boundaries, names and the status of Abyei are not an official UN endorsement.</p>',metricSelect)}${section(low?`${escapeHTML(low.state)} has the lowest observed contact rate`:'Calling, reach and verified completion','Counts are unique master-linked contact keys, not call attempts.',chartBox('state-performance','tall')+legend())}</div>`+
    section('How answers differ by area','These counts show which places contributed more or fewer answers. The records do not show why.',`<div class="geography-signals"><div class="insight"><h4>${under&&totalCompleted>=10?`${escapeHTML(under.state)}: ${pp(under.difference)} fewer replies than its share of the list`:'List comparison not available'}</h4><p>${under&&totalCompleted>=10?`${under.responseShare.toFixed(1)}% of ${number(totalCompleted)} people who finished and match the list are from ${escapeHTML(under.state)}. ${under.masterShare.toFixed(1)}% of the beneficiary list is from this state.`:'At least 10 finished surveys are needed to compare shares.'}</p></div><div class="insight"><h4>${priority?`${escapeHTML(priority.state)}: ${number(priority.neverAnswered)} called numbers did not answer`:'No call records'}</h4><p>${priority?`${number(priority.uncalled)} numbers on the list had no call; ${number(priority.answeredIncomplete)} people answered but did not finish; ${number(priority.invalidPhones)} numbers may be incorrect.`:'There are no calls matched to the beneficiary list.'}</p></div><div class="insight"><h4>${largestCommunity&&largestCommunity.completed>0?`${escapeHTML(largestCommunity.community)} has ${rate(largestCommunity.completed,totalCompleted,true)} of finished surveys`:'No finished surveys by community'}</h4><p>${largestCommunity&&largestCommunity.completed>0?`${escapeHTML(largestCommunity.state)} / ${escapeHTML(largestCommunity.locality)}: ${number(largestCommunity.completed)} finished surveys from ${number(largestCommunity.master)} numbers on the list.`:'No community names are available for completed surveys.'}</p></div></div>`)+
    section('State conversion: coverage, pickup and follow-through','Coverage = called/master; contact = reached/called. Started is a Q01 subscriber snapshot proxy, not a timestamped event; completion rates use their named denominator.',table(['State','Master keys','Called','Coverage / master','Selected attempts','Reached','Contact / called','Started · Q01 proxy','Completed','Complete / called','Complete / reached','Complete / started proxy','Complete / master','Mean selected attempts / called'],rows.map(row=>[stateButton(row),number(row.master),number(row.called),rate(row.called,row.master,true),number(row.attempts),number(row.reached),rate(row.reached,row.called,true),number(row.started),`${number(row.completed)}${row.completed<10?' <span class="pill">Small n</span>':''}`,rate(row.completed,row.called,true),rate(row.completed,row.reached,true),rate(row.completed,row.started,true),rate(row.completed,row.master,true),row.called?(row.attempts/row.called).toFixed(2):'—'])))+
    `<div class="split equal">${section('Where does nonresponse occur?','Disjoint contact groups sum to the master cohort in each state.',chartBox('state-nonresponse','tall'))}${section('Roster composition and respondent composition differ','Each series sums to 100% within its own master-linked cohort. Respondent percentages withheld if the total base is below 10.',chartBox('state-representation','tall'))}</div>`+
    section('Overrepresentation and underrepresentation are not population estimates','Index = respondent share / master share; 1.00 is proportional representation. Expected counts hold the current total completions fixed; they are not targets, missing responses or weights.',table(['State','Master share','Completer share','Gap (pp)','Representation index','Proportional benchmark count','Actual completed','Interpretation'],rows.map(row=>[escapeHTML(row.state),rate(row.master,totalMaster,true),rate(row.completed,totalCompleted,true),pp(row.difference),row.representationIndex!==null&&totalCompleted>=10?row.representationIndex.toFixed(2):'Withheld',row.expectedAtRosterShare===null||totalCompleted<10?'—':row.expectedAtRosterShare.toFixed(1),number(row.completed),totalCompleted<10?'Insufficient base':`${row.difference>0.05?'Overrepresented':row.difference<-.05?'Underrepresented':'Near proportional'}${row.completed<10?' · small n':''}`]))+`<p class="table-note">${number(count(scope.completed,person=>!person.in_master))} unmatched completed respondents are excluded. ${number(totalCompleted)} / ${number(scope.completed.length)} completed respondents are master-linked. ${scope.exposed?'The baseline is the selected calling-exposure cohort, not the full master roster.':'The baseline follows the shared filters and includes uncalled contacts.'} ${over&&totalCompleted>=10?`${escapeHTML(over.state)} has the largest positive share gap (${pp(over.difference)}).`:''}</p>`)+
    section('Calls and survey results by state','Counts separate numbers not called, numbers that did not answer, and people who answered but did not finish.',table(['State','Not called','Called, no answer','Never answered','Answered, no finished survey','No finished survey','Possibly incorrect numbers','Numbers called more than once'],rows.map(row=>[escapeHTML(row.state),number(row.uncalled),number(row.neverAnswered),number(row.uncalled+row.neverAnswered),number(row.answeredIncomplete),number(row.nonresponse),number(row.invalidPhones),number(row.repeatContacts)])))+
    '<div id="geography-detail"></div>';
  drawChart('state-performance',rows.map(row=>row.state),[{label:'Called',data:rows.map(row=>row.called),backgroundColor:COLORS.called},{label:'Reached',data:rows.map(row=>row.reached),backgroundColor:COLORS.reached},{label:'Completed',data:rows.map(row=>row.completed),backgroundColor:COLORS.completed}],{horizontal:true});
  drawChart('state-nonresponse',rows.map(row=>row.state),[{label:'Not called',data:rows.map(row=>row.uncalled),backgroundColor:COLORS.grey},{label:'Called, never answered',data:rows.map(row=>row.neverAnswered),backgroundColor:COLORS.unreached},{label:'Reached, no completed record',data:rows.map(row=>row.answeredIncomplete),backgroundColor:COLORS.reached},{label:'Completed',data:rows.map(row=>row.completed),backgroundColor:COLORS.completed}],{horizontal:true,stacked:true});
  drawChart('state-representation',rows.map(row=>row.state),[{label:'Master composition (%)',data:rows.map(row=>row.masterShare),backgroundColor:COLORS.called},{label:'Completed composition (%)',data:rows.map(row=>totalCompleted>=10?row.responseShare:null),backgroundColor:COLORS.completed}],{horizontal:true,percent:true});
  el('map-metric').value=local.mapMetric;el('map-metric').addEventListener('change',event=>{local.mapMetric=event.target.value;drawMap(rows);});drawMap(rows);
  document.querySelectorAll('[data-geo-state]').forEach(button=>button.addEventListener('click',()=>{el('state').value=button.dataset.geoState;render();}));
  exportRows=[...rows.map(geographyExport),...localities.map(geographyExport),...communities.map(geographyExport)];
  renderGeographyDetail(localities,communities);
}

function geographicMapMeasure(row){
  if(local.mapMetric==='count')return {label:'Finished surveys',value:row.completed,display:number(row.completed)};
  const measures={coverage:['Share of list called',row.called,row.master],contact:['Answered / called',row.reached,row.called],completion:['Finished survey / called',row.completed,row.called],reachedCompletion:['Finished survey / answered',row.completed,row.reached],masterCompletion:['Finished survey / list',row.completed,row.master]};
  const [label,numerator,denominator]=measures[local.mapMetric]||measures.contact;
  return {label,value:denominator>=10?100*numerator/denominator:null,display:`${rate(numerator,denominator,true)} (${number(numerator)} / ${number(denominator)})`};
}

function drawMap(rows){
  const container=el('state-map');container.innerHTML='';
  if(!MAP_DATA.features.length){container.innerHTML='<div class="empty">Map data is unavailable. State results are in the table.</div>';return;}
  const aliases={'Gezira':'Al Jazeera'},byState=new Map(rows.map(row=>[row.category,row]));
  const values=rows.map(row=>geographicMapMeasure(row).value).filter(value=>value!==null);
  const max=Math.max(...values,1),color=d3.scaleQuantize().domain([0,max]).range(POSITIVE_SCALE);
  if(el('map-scale-note'))el('map-scale-note').textContent=!values.length?'No state has enough calls to show a rate.':values.every(value=>value===0)?`${geographicMapMeasure(rows[0]).label}: all displayed values are zero.`:`${geographicMapMeasure(rows[0]).label}: colours range from 0 to ${local.mapMetric==='count'?number(max):max.toFixed(1)+'%'}. The scale changes with the filters.`;
  const features=MAP_DATA.features.map(feature=>{
    const copy=structuredClone(feature),polygons=copy.geometry.type==='Polygon'?[copy.geometry.coordinates]:copy.geometry.coordinates;
    for(const polygon of polygons)if(d3.geoArea({type:'Polygon',coordinates:polygon})>2*Math.PI)for(const ring of polygon)ring.reverse();
    return copy;
  });
  const geo={type:'FeatureCollection',features},projection=d3.geoMercator().fitExtent([[20,15],[540,365]],geo),path=d3.geoPath(projection);
  const svg=d3.select(container).append('svg').attr('viewBox','0 0 560 380').attr('role','img').attr('aria-label','Sudan states map');
  const tooltip=d3.select(container).append('div').attr('class','map-tooltip').style('display','none');
  svg.selectAll('path').data(geo.features).join('path').attr('d',path).attr('fill',feature=>{
    const state=aliases[feature.properties.shapeName]||feature.properties.shapeName,row=byState.get(state),value=row?geographicMapMeasure(row).value:null;
    return value===null?COLORS.noData:color(value);
  }).attr('data-state',feature=>byState.has(aliases[feature.properties.shapeName]||feature.properties.shapeName)?aliases[feature.properties.shapeName]||feature.properties.shapeName:null)
    .attr('tabindex',feature=>byState.has(aliases[feature.properties.shapeName]||feature.properties.shapeName)?0:null)
    .attr('role',feature=>byState.has(aliases[feature.properties.shapeName]||feature.properties.shapeName)?'button':null)
    .attr('aria-label',feature=>{const state=aliases[feature.properties.shapeName]||feature.properties.shapeName,row=byState.get(state);return row?`${state}: ${geographicMapMeasure(row).label} ${geographicMapMeasure(row).display}`:state;})
    .on('pointermove',(event,feature)=>{
      const state=aliases[feature.properties.shapeName]||feature.properties.shapeName,row=byState.get(state),bounds=container.getBoundingClientRect();
      tooltip.style('display','block').style('left',`${Math.min(event.clientX-bounds.left+12,bounds.width-210)}px`).style('top',`${Math.max(0,event.clientY-bounds.top-45)}px`)
        .html(`<strong>${escapeHTML(state)}</strong><br>${row?`${escapeHTML(geographicMapMeasure(row).label)}: ${escapeHTML(geographicMapMeasure(row).display)}<br>${number(row.master)} on the list · ${number(row.called)} called<br>${number(row.reached)} answered · ${number(row.completed)} finished`:'Not on the list'}`);
    }).on('pointerleave',()=>tooltip.style('display','none'))
    .on('click',(event,feature)=>{const state=aliases[feature.properties.shapeName]||feature.properties.shapeName;if(byState.has(state)){el('state').value=state;render();}})
    .on('keydown',(event,feature)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();const state=aliases[feature.properties.shapeName]||feature.properties.shapeName;if(byState.has(state)){el('state').value=state;render();}}});
}

function renderGeographyDetail(localities,communities){
  const units=geographyView.level==='Community'?communities:localities,search=geographyView.search.trim().toLocaleLowerCase();
  const rows=units.filter(row=>(!search||[row.state,row.locality,row.community].join(' ').toLocaleLowerCase().includes(search))&&(geographyView.gap==='all'||(geographyView.gap==='noCompletion'?row.completed===0:geographyView.gap==='neverReached'?row.reached===0:geographyView.gap==='uncalled'?row.uncalled>0:row.completed<10))).sort((a,b)=>b.neverAnswered-a.neverAnswered||b.master-a.master);
  const control=`<div class="control geography-detail-controls"><label>Area level<select id="geo-level"><option>Locality</option><option>Community</option></select></label><label>Show<select id="geo-gap"><option value="all">All areas</option><option value="noCompletion">No finished surveys</option><option value="neverReached">No one answered</option><option value="uncalled">Numbers not called</option><option value="small">Fewer than 10 finishes</option></select></label><label>Find an area<input type="search" id="geo-search" value="${escapeHTML(geographyView.search)}" placeholder="State, locality or community"></label></div>`;
  const headers=['State','Locality',...(geographyView.level==='Community'?['Community']:[]),'Numbers on list','Called','Answered','Finished survey','Not called','Called, no answer','Answer rate','Finished / called','Finished / answered','Share of finished surveys'];
  el('geography-detail').innerHTML=section('Locality and community counts',`${number(rows.length)} of ${number(units.length)} areas shown. Rows with the most unanswered calls appear first. Search and “Show” affect this table only.`,table(headers,rows.map(row=>[escapeHTML(row.state),escapeHTML(row.locality),...(geographyView.level==='Community'?[escapeHTML(row.community)]:[]),number(row.master),number(row.called),number(row.reached),`${number(row.completed)}${row.completed<10?' <span class="pill">Small n</span>':''}`,number(row.uncalled),number(row.neverAnswered),rate(row.reached,row.called,true),rate(row.completed,row.called,true),rate(row.completed,row.reached,true),rate(row.completed,count(scope.master,person=>person.response_complete),true)]))+`<p class="table-note">Areas use their state and parent locality so same-named places are not combined. No exact coordinates were supplied. Percentages are hidden when the total is below 10; “small n” means fewer than 10 finished surveys.</p>`,control);
  el('geo-level').value=geographyView.level;el('geo-gap').value=geographyView.gap;
  el('geo-level').addEventListener('change',event=>{geographyView.level=event.target.value;renderGeographyDetail(localities,communities);});
  el('geo-gap').addEventListener('change',event=>{geographyView.gap=event.target.value;renderGeographyDetail(localities,communities);});
  el('geo-search').addEventListener('input',event=>{geographyView.search=event.target.value;const caret=event.target.selectionStart;renderGeographyDetail(localities,communities);el('geo-search').focus();el('geo-search').setSelectionRange(caret,caret);});
}

function renderComparison(){
  const rows=masterComparisons(local.comparison),attribute=local.comparison,completed=sum(rows,'completed');
  const calledTotal=sum(rows,'called'),reachedTotal=sum(rows,'reached');
  const genderStates=[...groupBy(scope.master,person=>`${person.State}|${person.Gender}`)].map(([,people])=>({state:people[0].State,gender:people[0].Gender,master:people.length,called:count(people,person=>person.attempts>0),reached:count(people,person=>person.reached),completed:count(people,person=>person.response_complete)})).sort((a,b)=>a.state.localeCompare(b.state)||a.gender.localeCompare(b.gender));
  const controls=`<div class="control"><label>Compare by<select id="compare-by">${Object.entries(LABELS).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label></div>`;
  const groups=['Finished survey','Answered, did not finish','Called, did not answer','Not called'];
  el('content').innerHTML=heading('Who finished the survey?','Compare finished surveys with people who answered but did not finish, did not answer, or were not called.','People matched to the list')+
    `<div class="notice info"><strong>${number(completed)} people who finished the survey match the beneficiary list, out of ${number(scope.master.length)} phone numbers on the list.</strong> ${number(count(scope.completed,person=>!person.in_master))} finished surveys are not matched to the list and are left out of these comparisons.</div>`+
    `<div class="split equal">${section('Share of people in each group','Shows the share of the list and the share of finished surveys for each group. Percentages are hidden when fewer than 10 people finished.',chartBox('composition'),controls)}${section('Answer and survey finish rates','Percent of called phone numbers in each group. Small groups are not shown.',chartBox('group-rates'))}</div>`+
    section('Who was called, reached, and finished?','Each phone number is counted once. Group totals describe people, not the number of calls.',table([LABELS[attribute],...groups,'Called','Answered at least once','Share of list','Share of calls','Share of answers','Share of finished surveys','Difference (points)'],rows.map(row=>{const people=scope.master.filter(person=>person[attribute]===row.category);return [categoryLabel(row.category,attribute),...groups.map(group=>number(count(people,person=>person.status_group===group))),number(row.called),number(row.reached),`${row.masterShare.toFixed(1)}%`,rate(row.called,calledTotal,true),rate(row.reached,reachedTotal,true),completed>=10?`${row.responseShare.toFixed(1)}%`:'Not shown',row.difference!==null&&completed>=10?`${row.difference>0?'+':''}${row.difference.toFixed(1)}`:'—'];})))+
    (attribute==='Gender'?section('Women and men by state','Counts and rates are shown for each state. Percentages are hidden when fewer than 10 people were called.',table(['State','Gender','On the list','Called','Answered','Finished survey','Answered / called','Finished / called'],genderStates.map(row=>[escapeHTML(row.state),categoryLabel(row.gender,'Gender'),number(row.master),number(row.called),number(row.reached),number(row.completed),rate(row.reached,row.called,true),rate(row.completed,row.called,true)]))):'')+
    `<div class="notice">These are differences in the supplied records. They do not show why someone answered or finished. The beneficiary list is not a random sample of all farmers.</div>`;
  const top=rows.slice(0,14);
  drawChart('composition',top.map(row=>row.category),[{label:'On the beneficiary list (%)',data:top.map(row=>row.masterShare),backgroundColor:COLORS.called},{label:'Finished surveys (%)',data:top.map(row=>completed>=10?row.responseShare:null),backgroundColor:COLORS.completed}],{horizontal:true,percent:true});
  drawChart('group-rates',top.map(row=>row.category),[{label:'Answered at least once (%)',data:top.map(row=>row.called>=10?100*row.reached/row.called:null),backgroundColor:COLORS.reached},{label:'Finished survey / called (%)',data:top.map(row=>row.called>=10?100*row.completed/row.called:null),backgroundColor:COLORS.completed}],{horizontal:true,percent:true});
  if(rows.length>14)el('content').insertAdjacentHTML('beforeend','<p class="table-note">Charts show the 14 largest groups. The table includes all groups.</p>');
  el('compare-by').value=attribute;el('compare-by').addEventListener('change',event=>{local.comparison=event.target.value;render();});
  exportRows=rows.map(row=>({attribute,category:row.category,phone_numbers_on_list:row.master,called:row.called,answered:row.reached,finished_survey:row.completed,answered_did_not_finish:row.reached-row.completed,called_did_not_answer:row.called-row.reached,not_called:row.master-row.called,list_share:`${row.masterShare.toFixed(1)}%`,called_share:rate(row.called,calledTotal,true),answered_share:rate(row.reached,reachedTotal,true),finished_survey_share:completed>=10?`${row.responseShare.toFixed(1)}%`:'Not shown',difference_points:completed>=10?row.difference:'Not shown'}));
  if(attribute==='Gender')exportRows.push(...genderStates.map(row=>({attribute:'Gender within State',state:row.state,category:row.gender,phone_numbers_on_list:row.master,called:row.called,answered:row.reached,finished_survey:row.completed,answer_rate:rate(row.reached,row.called,true),survey_finish_rate:rate(row.completed,row.called,true)})));
}

function callGroups(dimension){
  const weekdayNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const grouped=groupBy(scope.calls,call=>dimension==='weekday'?weekdayNames[new Date(call.date+'T12:00:00Z').getUTCDay()]:call[dimension]);
  return [...grouped].map(([label,calls])=>{const phones=new Set(calls.map(call=>call.person_id));return {label,attempts:calls.length,answered:count(calls,call=>call.answered),phones:phones.size,cohortCompleted:count(scope.completed,person=>phones.has(person.person_id))};}).sort((a,b)=>dimension==='weekday'?weekdayNames.indexOf(a.label)-weekdayNames.indexOf(b.label):String(a.label).localeCompare(String(b.label),undefined,{numeric:true}));
}

function retryYield(){
  const calls=DATA.calls.filter(call=>scope.ids.has(call.person_id)).sort((a,b)=>a.person_id.localeCompare(b.person_id)||a.date.localeCompare(b.date)||a.scheduled_time.localeCompare(b.scheduled_time)||a.attempt_id-b.attempt_id);
  const sequences=new Map(),reached=new Set(),bins=new Map(),selectedIDs=new Set(scope.calls.map(call=>call.attempt_id));
  for(const call of calls){const sequence=(sequences.get(call.person_id)||0)+1;sequences.set(call.person_id,sequence);if(selectedIDs.has(call.attempt_id)&&!reached.has(call.person_id)){if(!bins.has(sequence))bins.set(sequence,{sequence,atRisk:0,newlyReached:0});const row=bins.get(sequence);row.atRisk++;if(call.answered)row.newlyReached++;}if(call.answered)reached.add(call.person_id);}
  return [...bins.values()].sort((a,b)=>a.sequence-b.sequence);
}

function renderCalls(){
  const s=scope,rows=callGroups(local.callDimension),hours=callGroups('hour'),yieldRows=retryYield(),answered=count(s.calls,call=>call.answered);
  const bands=['1','2','3','4+'].map(band=>{const people=s.called.filter(person=>band==='4+'?person.attempts>=4:person.attempts===Number(band));return {band,phones:people.length,reached:count(people,person=>person.reached),completed:count(people,person=>person.response_complete)};});
  const causes=[...groupBy(s.calls.filter(call=>!call.answered),'hangup')].map(([cause,calls])=>({cause,attempts:calls.length,phones:new Set(calls.map(call=>call.person_id)).size})).sort((a,b)=>b.attempts-a.attempts);
  const controls='<div class="control"><label>Time grouping<select id="call-dimension"><option value="date">Scheduled date</option><option value="weekday">Scheduled weekday</option><option value="hour">Scheduled hour</option></select></label></div>';
  el('content').innerHTML=heading('Pickup is the main operational bottleneck.','Time charts use scheduled local time (+02:00), not verified failed-call dial time. Completion cannot be attributed to a call event.','Observed rows, not retry counter')+
    `<div class="metrics">${metric('Answered log rows',number(answered),`${rate(answered,s.calls.length)} / ${number(s.calls.length)} selected rows`,'reached')}${metric('Unanswered log rows',number(s.calls.length-answered),'Includes no-answer and technical errors','unreached')}${metric('Repeat-call contacts',number(count(s.called,person=>person.attempts>1)),`${rate(count(s.called,person=>person.attempts>1),s.called.length)} of called contacts · full-export attempts`,'called')}${metric('Mean observed attempts',(s.called.length?s.calls.length/s.called.length:0).toFixed(2),`${number(s.calls.length)} selected rows / ${number(s.called.length)} called contacts`)}</div>`+
    `<div class="notice"><strong>Timing is observational.</strong> ${number(count(s.calls,call=>call.prelaunch))} selected rows precede the reported 8 September launch. All scheduled hours in the full export are inside 09:00–20:00. Allocation differs by date, state and retry sequence; high pickup at one hour is not proof of an optimal window.</div>`+
    `<div class="split equal">${section('Batch scheduling drives call volume','Answered versus unanswered call-log rows, not beneficiaries.',chartBox('call-pattern'),controls)}${section('Scheduled-hour pickup varies','Answered rows / all rows at each hour. A one-row hour is not a reliable rate.',chartBox('hour-pickup'))}</div>`+
    section('Calling exposure and completed-response overlap','Completed contacts in each time cohort may appear in multiple rows. This is NOT event-level completion or a completed-at-this-hour rate.',table([local.callDimension==='date'?'Scheduled date':local.callDimension==='weekday'?'Weekday':'Hour (+02:00)','Log rows','Answered','Unanswered','Answer rate','Unique contacts','Ever-completed overlap'],rows.map(row=>[escapeHTML(row.label),number(row.attempts),number(row.answered),number(row.attempts-row.answered),rate(row.answered,row.attempts,true),number(row.phones),number(row.cohortCompleted)])))+
    `<div class="split equal">${section('Who received more observed calls?','Final attempt count across the full export; retries are selected by prior outcomes.',table(['Attempt band','Contacts','Ever reached','Completed','Contact rate','Complete / contacts'],bands.map(row=>[row.band,number(row.phones),number(row.reached),number(row.completed),rate(row.reached,row.phones,true),rate(row.completed,row.phones,true)])))}${section('What did the next attempt add?','New reach / previously unreached contacts at each observed sequence. Prior history uses all export rows.',table(['Sequence','Previously unreached','Newly reached','Conditional pickup'],yieldRows.map(row=>[row.sequence,number(row.atRisk),number(row.newlyReached),rate(row.newlyReached,row.atRisk,true)])))}</div>`+
    section('Reasons calls did not connect','The call system records these reasons. A phone number may appear more than once.',table(['Call result code','Calls not answered','Phone numbers','Share of calls not answered'],causes.map(row=>[escapeHTML(row.cause),number(row.attempts),number(row.phones),rate(row.attempts,s.calls.length-answered,true)])))+
    '<p class="table-note">The supplied platform Call Attempts field is retained in the analytical model but never summed for funnel counts. Additional retries and completion associations are confounded by retry selection and undated responses.</p>';
  drawChart('call-pattern',rows.map(row=>local.callDimension==='date'?row.label.slice(5):String(row.label)),[{label:'Answered rows',data:rows.map(row=>row.answered),backgroundColor:COLORS.reached},{label:'Unanswered rows',data:rows.map(row=>row.attempts-row.answered),backgroundColor:COLORS.unreached}],{stacked:true});
  drawChart('hour-pickup',hours.map(row=>`${String(row.label).padStart(2,'0')}:00`),[{label:'Answer rate (%)',data:hours.map(row=>row.attempts>=10?100*row.answered/row.attempts:null),backgroundColor:COLORS.reached}],{percent:true});
  el('call-dimension').value=local.callDimension;el('call-dimension').addEventListener('change',event=>{local.callDimension=event.target.value;render();});
  exportRows=[...rows.map(row=>({table:'time',grouping:local.callDimension,category:row.label,attempts:row.attempts,answered:row.answered,answer_rate:rate(row.answered,row.attempts,true),contacts:row.phones,undated_completed_overlap:row.cohortCompleted})),...bands.map(row=>({table:'final_attempt_cohort',category:row.band,contacts:row.phones,ever_reached:row.reached,completed:row.completed,contact_rate:rate(row.reached,row.phones,true),completion_rate:rate(row.completed,row.phones,true)})),...yieldRows.map(row=>({table:'incremental_reach',category:row.sequence,previously_unreached:row.atRisk,newly_reached:row.newlyReached,conditional_pickup:rate(row.newlyReached,row.atRisk,true)})),...causes.map(row=>({table:'unanswered_cause',category:row.cause,attempts:row.attempts,contacts:row.phones}))];
}

function renderSurvey(){
  const question=local.question,metadata=DATA.questions[question],completed=scope.completed;
  const respondents=completed.filter(person=>ANSWER_MAP.get(person.person_id)?.[question]);
  const answers=[...new Set(DATA.answers.filter(row=>row.question===question).map(row=>row.answer))].sort();
  const counts=answers.map(answer=>({answer,count:count(respondents,person=>ANSWER_MAP.get(person.person_id)[question]===answer)}));
  const progressionQuestions=['R1Q01','R1Q03','R1Q04','R1Q05','R1Q06','R1Q09','R1Q10','R1Q11','R1Q12','R1Q13'];
  const progressionBase=scope.people.filter(person=>QUESTION_PRESENCE.has(`${person.person_id}|R1Q01`));
  const snapshotCounts=Object.fromEntries(Object.keys(DATA.questions).map(id=>[id,count(progressionBase,person=>QUESTION_PRESENCE.has(`${person.person_id}|${id}`))]));
  const transitionDefinitions=[
    {from:'R1Q01',to:'R1Q03',caveat:'Q02 eligibility/routing is unverified'},
    {from:'R1Q03',to:'R1Q04'},
    {from:'R1Q04',to:'R1Q05'},
    {from:'R1Q05',to:'R1Q06'},
    {from:'R1Q06',to:'R1Q09',caveat:'Spans unverified Q07/Q08 routing'},
    {from:'R1Q09',to:'R1Q10'},
    {from:'R1Q10',to:'R1Q11'},
    {from:'R1Q11',to:'R1Q12'},
    {from:'R1Q12',to:'R1Q13'},
  ];
  const transitions=transitionDefinitions.map(definition=>{
    const before=progressionBase.filter(person=>QUESTION_PRESENCE.has(`${person.person_id}|${definition.from}`));
    const after=progressionBase.filter(person=>QUESTION_PRESENCE.has(`${person.person_id}|${definition.to}`));
    const afterIDs=new Set(after.map(person=>person.person_id));
    const beforeIDs=new Set(before.map(person=>person.person_id));
    const retained=count(before,person=>afterIDs.has(person.person_id));
    return {...definition,before:before.length,after:after.length,retained,lost:before.length-retained,gained:count(after,person=>!beforeIDs.has(person.person_id))};
  });
  const directTransitions=transitions.filter(row=>!row.caveat&&row.before>0);
  const largestDirectLoss=[...directTransitions].sort((first,second)=>second.lost-first.lost)[0];
  const largestObservedLoss=[...transitions].sort((first,second)=>second.lost-first.lost)[0];
  const finalRecorded=snapshotCounts.R1Q13||0;
  const startToFinalGap=progressionBase.length-finalRecorded;
  const completerQuestionCounts=Object.fromEntries(Object.keys(DATA.questions).map(id=>[id,count(completed,person=>Boolean(ANSWER_MAP.get(person.person_id)?.[id]))]));
  const grouped=[...groupBy(completed,local.surveyGroup)].map(([category,people])=>{const valid=people.filter(person=>ANSWER_MAP.get(person.person_id)?.[question]);return {category,completed:people.length,answered:valid.length,missing:people.length-valid.length,counts:answers.map(answer=>count(valid,person=>ANSWER_MAP.get(person.person_id)[question]===answer))};}).sort((a,b)=>b.completed-a.completed);
  const controls=`<div class="control"><label>Question<select id="question">${Object.entries(DATA.questions).map(([id,question])=>`<option value="${id}">${id} · ${escapeHTML(question.title)}</option>`).join('')}</select></label></div>`;
  const groupControl=`<div class="control"><label>Compare by<select id="survey-group">${Object.entries(LABELS).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label></div>`;
  el('content').innerHTML=heading('Completed respondents: what did they report?','Only the completed-response file supplies these answers. Results are unweighted and not representative of all Sudanese farmers.','Verified response file')+
    `<div class="metrics">${metric('Completed respondent cohort',number(completed.length),'Unique phone keys in the current filtered cohort','completed')}${metric('Answered selected item',number(respondents.length),`${rate(respondents.length,completed.length,true)} of ${number(completed.length)} completers`)}${metric('Missing / not applicable',number(completed.length-respondents.length),'Branch eligibility is not fully documented')}${metric('Master-linked completers',number(count(completed,person=>person.in_master)),`${rate(count(completed,person=>person.in_master),completed.length,true)} of completed respondents`)}</div>`+
    section('Where are answer records thinning out?','Call-log question fields are subscriber snapshots, not question events or hang-up timestamps. A missing answer flag is a possible stopping point, not a confirmed drop-off.',`<div class="metrics">${metric('Q01 start proxy',number(progressionBase.length),'Contacts with Q01 snapshot; started flag is empty')}${metric('Q13 final-item snapshot',number(finalRecorded),`${rate(finalRecorded,progressionBase.length,true)} of Q01 snapshot contacts`,'completed')}${metric('Q01-to-Q13 record gap',number(startToFinalGap),`${rate(startToFinalGap,progressionBase.length,true)} of Q01 snapshot contacts`,'unreached')}${metric('Largest clear adjacent loss',largestDirectLoss?number(largestDirectLoss.lost):'—',largestDirectLoss?`${largestDirectLoss.from.slice(2)} → ${largestDirectLoss.to.slice(2)} · ${rate(largestDirectLoss.lost,largestDirectLoss.before,true)} of prior answerers`:'No transition base')}</div>`+
    `<div class="notice info"><strong>Largest recorded answer gaps:</strong> ${largestDirectLoss?`${largestDirectLoss.from} → ${largestDirectLoss.to}: ${number(largestDirectLoss.lost)} of ${number(largestDirectLoss.before)} people have no saved answer for the next question (${rate(largestDirectLoss.lost,largestDirectLoss.before,true)}).`: 'No direct question-to-question count is available.'} ${largestObservedLoss&&largestObservedLoss.caveat?`The largest gap is ${largestObservedLoss.from} → ${largestObservedLoss.to} (${number(largestObservedLoss.lost)} of ${number(largestObservedLoss.before)}), but ${escapeHTML(largestObservedLoss.caveat)}.`:''} Q13 has 133 saved answers in the call file, but there are 116 surveys in the completed-survey file. These records do not show when a caller left the survey.</div>`+
    `<div class="split equal">${section('Saved answers to the main questions','Share of people with a Q01 answer who also have a saved answer to each question. Q02, Q07 and Q08 are shown separately because they may only be asked in some cases.',chartBox('snapshot-progression','tall'))}${section('Questions asked only in some cases','Counts among people with a saved Q01 answer. The files do not show who should have been asked each question.',table(['Question','Saved answers','Share of Q01 answers','Note'],['R1Q02','R1Q07','R1Q08'].map(id=>[`${id} · ${escapeHTML(DATA.questions[id].title)}`,number(snapshotCounts[id]),rate(snapshotCounts[id],progressionBase.length,true),id==='R1Q07'?'35/47 completed-survey answers are from people whose income did not increase':'The exact skip rule was not provided']))+`<p class="table-note">The Q06-Q08 question skip rules were not included with the data.</p>`)}</div>`+
    section('Step-to-step answer presence','Loss = prior-checkpoint answerers without a recorded answer at the next checkpoint / prior answerers. Branch-spanning rows cannot identify which intervening item caused an exit.',table(['Checkpoint transition','Prior answers','Next answers','Recorded at both','No next answer recorded','Loss / prior answers','Interpretation'],transitions.map(row=>[`${row.from} → ${row.to}`,number(row.before),number(row.after),number(row.retained),number(row.lost),rate(row.lost,row.before,true),row.caveat?escapeHTML(row.caveat):'Adjacent checkpoint']))+`<p class="table-note">Counts use the selected contact cohort but include lifetime snapshot fields. Date/outcome filters select exposed contacts, not answers observed during that call period.</p>`)+
    section('Completed-file question availability: separate denominator','Counts come from the 116-record completed-response file. Missing fields among completers cannot locate where non-completers left the call.',`<div class="chart small"><canvas id="completed-question-availability" role="img" aria-label="Completed-response item availability"></canvas></div>`+table(['Item','Completed-file answers','No answer recorded','Share of completed records'],Object.keys(DATA.questions).map(id=>[`${id} · ${escapeHTML(DATA.questions[id].title)}`,number(completerQuestionCounts[id]),number(completed.length-completerQuestionCounts[id]),rate(completerQuestionCounts[id],completed.length,true)])))+
    `<div class="notice info">The files do not show when each question was asked or when callers ended the call.</div>`)+
    `<div class="notice ${question==='R1Q07'?'danger':'info'}"><strong>${question}: ${escapeHTML(metadata.title)}.</strong> ${escapeHTML(metadata.note)} ${question==='R1Q07'?'Descriptive audit only: 35 of 47 full-file Q07 answers come from people not reporting increased income. Percentages below use observed answers, not an eligible population.':''}</div>`+
    section('Answer distribution','Percent of non-missing selected-item answers. Counts are always retained.',chartBox('answer-distribution')+table(['Recorded answer','Count','Share of item answers'],counts.map(row=>[escapeHTML(row.answer),number(row.count),rate(row.count,respondents.length,true)])),controls)+
    section('Subgroup answers with explicit bases','Cells show count / subgroup non-missing item answers and percent; percent withheld when that base is below 10.',table([LABELS[local.surveyGroup],'Completers','Item answers','Missing / N/A',...answers.map(escapeHTML)],grouped.map(row=>[escapeHTML(row.category),number(row.completed),number(row.answered),number(row.missing),...row.counts.map(value=>`${number(value)} / ${number(row.answered)} · ${rate(value,row.answered,true)}`)])),groupControl)+
    '<p class="table-note">Subgroup sample sizes describe respondents, not the underlying population. Item denominators exclude missing answers. Conditional questions cannot be interpreted as dropout without questionnaire routing and event logs.</p>';
  drawChart('answer-distribution',counts.map(row=>row.answer),[{label:'Share of observed item answers (%)',data:counts.map(row=>respondents.length>=10?100*row.count/respondents.length:null),backgroundColor:counts.map((row,index)=>CATEGORICAL[index%CATEGORICAL.length])}],{horizontal:true,percent:true});
  drawChart('snapshot-progression',progressionQuestions.map(id=>id.slice(2)),[{label:'Recorded answers / Q01 snapshot (%)',data:progressionQuestions.map(id=>progressionBase.length>=10?100*snapshotCounts[id]/progressionBase.length:null),backgroundColor:progressionQuestions.map(id=>id==='R1Q01'?COLORS.called:id==='R1Q06'?paletteColor('dark-yellow'):COLORS.completed)}],{horizontal:true,percent:true});
  drawChart('completed-question-availability',Object.keys(DATA.questions).map(id=>id.slice(2)),[{label:'Completed-file answers',data:Object.keys(DATA.questions).map(id=>completerQuestionCounts[id]),backgroundColor:Object.keys(DATA.questions).map(id=>['R1Q02','R1Q07','R1Q08'].includes(id)?paletteColor('dark-yellow'):COLORS.completed)}],{horizontal:true});
  el('question').value=question;el('question').addEventListener('change',event=>{local.question=event.target.value;render();});
  el('survey-group').value=local.surveyGroup;el('survey-group').addEventListener('change',event=>{local.surveyGroup=event.target.value;render();});
  exportRows=[...transitions.map(row=>({table:'Question progression snapshot',transition:`${row.from} to ${row.to}`,prior_answerers:row.before,next_answerers:row.after,recorded_at_both:row.retained,no_next_answer_recorded:row.lost,loss_rate:rate(row.lost,row.before,true),routing_caveat:row.caveat||''})),...Object.keys(DATA.questions).map(id=>({table:'Question presence',question:id,title:DATA.questions[id].title,call_log_answer_snapshots:snapshotCounts[id],q01_snapshot_base:progressionBase.length,completed_file_answers:completerQuestionCounts[id],completed_file_base:completed.length,completed_file_answer_rate:rate(completerQuestionCounts[id],completed.length,true)})),...counts.map(row=>({table:'Selected question answer',question,group:'Overall',answer:row.answer,count:row.count,item_answer_base:respondents.length,completed_base:completed.length,percent:rate(row.count,respondents.length,true)})),...grouped.flatMap(row=>answers.map((answer,index)=>({table:'Selected question answer',question,group:row.category,group_attribute:local.surveyGroup,answer,count:row.counts[index],item_answer_base:row.answered,completed_base:row.completed,percent:rate(row.counts[index],row.answered,true)})))];
}

function renderQuality(){
  const q=DATA.quality,s=scope,matchedCalls=count(s.calls,call=>PHONE_MAP.get(call.person_id).in_master),matchedResponses=count(s.completed,person=>person.in_master);
  const selectedReconciliation=q.reconciliation.slice(0,6);
  const unmatched=s.people.filter(person=>!person.in_master);
  const unmatchedGroups=[...groupBy(unmatched,'State')].map(([state,people])=>[escapeHTML(state),number(people.length),number(count(people,person=>person.attempts>0)),number(count(people,person=>person.response_complete))]);
  el('content').innerHTML=heading('Trust the linkage. Keep the discrepancies visible.','The matching metrics follow filters. The source audit and September report reconciliation are fixed full-export reference checks.','No silent reconciliation')+
    `<div class="metrics">${metric('Call-row master match',rate(matchedCalls,s.calls.length),`${number(matchedCalls)} / ${number(s.calls.length)} selected rows`,'called')}${metric('Called-key master match',rate(count(s.called,person=>person.in_master),s.called.length),`${number(count(s.called,person=>person.in_master))} / ${number(s.called.length)} selected called contacts`,'called')}${metric('Response master match',rate(matchedResponses,s.completed.length),`${number(matchedResponses)} / ${number(s.completed.length)} selected responses`,'completed')}${metric('Unmatched contacts',number(unmatched.length),`${number(count(unmatched,person=>person.response_complete))} selected completed responses`,'unreached')}</div>`+
    section('The source audit: full export, not filtered','Original files were preserved; SHA-256 hashes and cleaning rules are recorded in the analytical outputs.',table(['Source / issue','Full-file count','Implication'],[
      ['Master records / contact keys','3,000 / 3,000','Roster differs from 3,002 observed called keys'],
      ['Invalid master phone values','46','Never repaired by guessed digits'],
      ['Flagged-invalid exact matched call rows','57','Prefix transformation links malformed values; not valid phones'],
      ['Duplicate master phone keys / exact rows','0 / 0','No observed master-key multiplicity; keep separate grains'],
      ['Duplicate completed-response keys / rows','0 / 0','116 unique raw completers'],
      ['Repeated called contact keys','933','Multiple calls are not duplicate beneficiaries'],
      ['Distinct Delivery IDs / log rows','4,118 / 4,118','One observed attempt record per Delivery ID'],
      ['Completed raw records / log flags / report','116 / 133 / 117','17 flagged contacts absent from raw completed file'],
      ['Pre-launch rows / contacts / completers','9 / 4 / 3','Scope begins before reported 8 September launch'],
      ['Q07 answers outside increased-income group','35 / 47','Routing or field semantics require investigation'],
      ['Missing or implausible master ages',number(q.age_invalid_or_missing),'Only 15–100 retained for age-band analysis'],
      ['Unreliable code-to-label mappings',number(q.mapping_issues.length),'Conflicting locality / unknown gender label withheld'],
      ['Question-counter field','All zero','Cannot define starts or completion from this field'],
      ['Independent target roster / completion timestamps','Not supplied','Targeting proxy and exposure-cohort date filters']
    ]))+
    `<div class="split equal">${section('Report versus underlying records','Full export, including pre-launch calls. Different definitions/snapshots are not forced to agree.',table(['Metric','Reported','Recomputed','Difference'],selectedReconciliation.map(row=>[escapeHTML(row.metric),number(row.reported),number(row.recomputed),`${row.difference>0?'+':''}${row.difference}`])))}${section('Selected unmatched contacts','Counts only; phone-level exceptions remain in the restricted local audit.',table(['Mapped state','Contact keys','Called','Completed'],unmatchedGroups)+`<p class="table-note">${number(count(s.master,person=>!person.phone_valid))} selected master contacts have invalid phone values. ${number(count(s.people,person=>person.log_complete&&!person.response_complete))} selected contacts have only a log completion flag. No identifiers are exported from this dashboard.</p>`)}</div>`+
    section('Every rate has a denominator','Contact keys are not proven unique individuals.',table(['Indicator','Numerator','Denominator'],[
      ['Contact rate','Unique contacts ever answered','Unique contacts called'],['Attempt answer rate','Answered selected log rows','All selected log rows'],['Completion / called','Raw completed-response contacts','Called contact cohort'],['Completion / reached','Raw completed-response contacts ever reached','Ever-reached contact cohort'],['Completion / started proxy','Raw completed-response contacts','Contacts with a Q01 snapshot'],['Repeat-call rate','Called contacts with >1 full-export row','Called contacts'],['Roster completion','Master-linked completed contacts','Master phone keys'],['Respondent share by group','Master-linked completers in group','All master-linked completers'],['Survey answer percentage','Selected answer count','Non-missing answers for that question/group']]))+
    section('Methodology and interpretation','Local reproducibility: python analyze.py; python -m unittest test_analysis -v.',`<dl class="method-list"><div><dt>Survey context</dt><dd>UNDP/Viamo beneficiary monitoring of livelihoods, service access and behavioural outcomes. The narrative describes 13 IVR questions, Sudanese Arabic translation and pre-testing, with Round 1 launch on 8 September. No independent consent, language-access or routing evidence is supplied.</dd></div><div><dt>Linking and labels</dt><dd>Sudan numbers normalize to +249 plus nine national digits starting 1 or 9. Invalid exact digit matches remove only the known export's 249 prefix and stay invalid. Master values take precedence. Codes backfill only through an unambiguous master mapping; no fuzzy label or number inference.</dd></div><div><dt>Grain and relationships</dt><dd>Master records → contact keys is many-to-one. Calls and responses link to a single contact dimension without multiplying rows. Finished (complete) means natural call end. Started is a Q01 snapshot proxy, since every started flag is empty.</dd></div><div><dt>Date and outcome filters</dt><dd>Filters select contacts exposed to matching scheduled calls and select those call rows. Ever reach, attempt-band classification, completed responses and question answers remain full-export contact evidence, not events inside the selected period. Without exposure filters, the master includes uncalled contacts.</dd></div><div><dt>Nonresponse and inference</dt><dd>Coverage, reach and response are selected processes. This is a programme roster, not a probability sample of Sudanese farmers. State and gender gaps are observational; do not attribute causes or generalize income figures nationally. No survey weighting is applied.</dd></div><div><dt>Privacy and disclosure</dt><dd>Names, phones, subscriber IDs and delivery IDs are absent here. The detailed pseudonymous model is still sensitive. The private phone audit is necessary for corrections and must not be distributed. Public release needs access controls and additional small-cell disclosure review.</dd></div></dl>`)+
    section('Question-count reconciliation','Full-export distinct subscriber snapshots; not call-event answers or an attrition curve.',table(['Question','Reported','Snapshot count','Difference'],q.reconciliation.slice(6).map(row=>[escapeHTML(row.metric),number(row.reported),number(row.recomputed),`${row.difference>0?'+':''}${row.difference}`])))+
    section('Mappings withheld rather than guessed','Master labels are retained even when a code cannot support a reliable fallback.',table(['Attribute','Encoded key','Reference labels','Reliable fallback'],q.mapping_issues.map(row=>[escapeHTML(row.attribute),escapeHTML(row.code),escapeHTML(row.labels),'No'])))+
    `<div class="notice danger"><strong>Missing evidence:</strong> exact questionnaire and branching rules, target-allocation list, carrier-level retry definitions, test-contact markers, survey event timestamps and the unexplained additional report completion. These gaps prevent verified in-window completion, causal time optimization and definitive question-dropout claims.</div>`;
  exportRows=[{metric:'Selected call rows matched master',numerator:matchedCalls,denominator:s.calls.length,percent:rate(matchedCalls,s.calls.length)},{metric:'Selected response records matched master',numerator:matchedResponses,denominator:s.completed.length,percent:rate(matchedResponses,s.completed.length)},...q.reconciliation.map(row=>({scope:'Fixed full-export reference',...row}))];
}

function render(){
  if(el('from').value&&el('to').value&&el('from').value>el('to').value){el('filter-error').hidden=false;el('filter-error').textContent='The start date must be before the end date.';charts.forEach(chart=>chart.destroy());charts=[];exportRows=[];el('content').innerHTML='<div class="empty">Please choose a valid date range.</div>';el('scope-count').textContent='Date range needs changing';return;}
  el('filter-error').hidden=true;
  charts.forEach(chart=>chart.destroy());charts=[];scope=getScope();
  el('scope-count').textContent=simpleText(`${number(scope.people.length)} phone numbers · ${number(scope.calls.length)} calls matching filters · ${number(scope.completed.length)} finished surveys`);
  el('scope-note').textContent=simpleText(scope.exposed?'Call date/result filters choose who is shown. Saved answers do not have dates.':'All files shown · Calls run 2–29 September and include 9 calls before the 8 September launch.');
  if(!scope.people.length){el('content').innerHTML=heading('No results for these filters.','Clear one or more filters to see results.')+'<div class="empty">No matching survey records.</div>';exportRows=[];return;}
  ({overview:renderOverview,geography:renderGeography,comparison:renderComparison,calls:renderCalls,survey:renderSurvey,quality:renderQuality})[currentPage]();
  simplifyRenderedText(el('content'));
  lucide.createIcons();
  document.querySelectorAll('nav button').forEach(button=>{button.classList.toggle('active',button.dataset.page===currentPage);button.setAttribute('aria-current',button.dataset.page===currentPage?'page':'false');});
}

function downloadCSV(){
  if(!exportRows.length)return;
  const filters=Object.entries(scope.values).filter(([,value])=>value).map(([key,value])=>`${key}=${value}`).join('; ')||'All supplied export rows and full roster';
  const rows=exportRows.map(row=>({...row,filter_context:filters,completion_time_basis:'Undated full-export contact snapshot'}));
  const headers=[...new Set(rows.flatMap(row=>Object.keys(row)))];
  const csvCell=value=>{let safe=String(value??'');if(/^[=+@\-]/.test(safe))safe="'"+safe;return '"'+safe.replaceAll('"','""')+'"';};
  const csv=[headers.map(csvCell).join(','),...rows.map(row=>headers.map(header=>csvCell(row[header])).join(','))].join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),anchor=document.createElement('a');anchor.href=url;anchor.download=`sudan-ivr-${currentPage}-aggregate.csv`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

Chart.defaults.font.family='Inter';Chart.defaults.color=COLORS.text;
Chart.defaults.scale.grid.color=COLORS.grid;
for(const [id,property] of [['state','State'],['gender','Gender'],['support','Type of Support']]){
  const values=[...new Set(DATA.people.map(person=>person[property]))].filter(value=>value!=='Unknown / unmatched').sort();for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;el(id).append(option);}
}
for(const id of ['state','gender','from','to','outcome','attempts','completion','support'])el(id).addEventListener('change',render);
document.querySelectorAll('nav button').forEach(button=>button.addEventListener('click',()=>{currentPage=button.dataset.page;location.hash=currentPage;render();}));
el('reset').addEventListener('click',()=>{for(const id of ['state','gender','from','to','outcome','attempts','completion','support'])el(id).value='';render();});
el('export').addEventListener('click',downloadCSV);el('print').addEventListener('click',()=>window.print());
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(['overview','geography','comparison','calls','survey','quality'].includes(page)){currentPage=page;render();}});
if(['overview','geography','comparison','calls','survey','quality'].includes(location.hash.slice(1)))currentPage=location.hash.slice(1);
render();